func parseSMI(out string) (name string, total, free uint64, ok bool) {
	line := strings.TrimSpace(strings.Split(strings.TrimSpace(out), "\n")[0])
	if line == "" {
		return "", 0, 0, false
	}
	parts := strings.Split(line, ",")
	if len(parts) < 3 {
		return "", 0, 0, false
	}
	name = strings.TrimSpace(parts[0])
	total = mibToBytes(parts[1])
	free = mibToBytes(parts[2])
	if total == 0 {
		return "", 0, 0, false
	}
	return name, total, free, true
}

func mibToBytes(s string) uint64 {
	s = strings.TrimSpace(s)
	if s == "" || strings.EqualFold(s, "[N/A]") {
		return 0
	}
	v, err := strconv.ParseUint(s, 10, 64)
	if err != nil {
		// Some drivers report "8192 MiB".
		f := strings.Fields(s)
		if len(f) > 0 {
			if v2, err2 := strconv.ParseUint(f[0], 10, 64); err2 == nil {
				return v2 * 1024 * 1024
			}
		}
		return 0
	}
	return v * 1024 * 1024
}

func physicalCores(ctx context.Context, run Runner) (int, bool) {
	if out, err := run(ctx, "wmic", "cpu", "get", "NumberOfCores", "/value"); err == nil {
		for _, line := range strings.Split(out, "\n") {
			line = strings.TrimSpace(strings.TrimPrefix(strings.TrimSpace(line), "\ufeff"))
			if v, ok := strings.CutPrefix(line, "NumberOfCores="); ok {
				if n, err := strconv.Atoi(strings.TrimSpace(v)); err == nil && n > 0 {
					return n, true
				}
			}
		}
	}
	if out, err := run(ctx, "powershell", "-NoProfile", "-Command",
		"(Get-CimInstance Win32_Processor).NumberOfCores"); err == nil {
		fields := strings.Fields(out)
		if len(fields) > 0 {
			if n, err := strconv.Atoi(fields[0]); err == nil && n > 0 {
				return n, true
			}
		}
	}
	return 0, false
}

